sign=lambda x:(x>0)-(x<0)
for col in [4,5,6,7]:
 out={'positive':0,'negative':0,'same_as_average':0,'ideal_equals_average':0}
 for cat,ex,a,i,*others in rows:
  s=([cat,ex,a,i]+others)[col]
  if a==i: out['ideal_equals_average']+=1
  elif a==s: out['same_as_average']+=1
  elif (a-s)*sign(a-i)>0:out['positive']+=1
  else:out['negative']+=1
 print(['cat','ex','average','ideal','good','paradigm','prototype','composite'][col],out)
for c in range(1,9):
 r=[v for v in rows if v[0]==c]
 print('Category',c,'means',*[round(sum(v[k] for v in r)/len(r),4) for k in [2,3,7]])
for n,k in [(36,24),(36,26),(46,39)]:
 print('One-sided binomial:',n,k,sum(comb(n,i) for i in range(k,n+1))/2**n)
